public async Task<CustomerSquareRetryResponse> Handle(RetryCustomerSquareTransactionQuery query, CancellationToken cancellationToken)
    {
        var order = await CustomerCheckoutSupport.LoadOwnedOrderAsync(dbContext, currentUser, query.OrderUuid, cancellationToken);
        if (string.IsNullOrWhiteSpace(_options.Square.AppId) || string.IsNullOrWhiteSpace(_options.Square.CallbackUrl))
        {
            return new CustomerSquareRetryResponse(0, null, null, "Square is not configured in the new API.");
        }

        var cents = ((int)Math.Round(order.Total * 100, MidpointRounding.AwayFromZero)).ToString(CultureInfo.InvariantCulture);
        var data = $"{{\"amount_money\":{{\"amount\":\"{cents}\",\"currency_code\":\"USD\"}},\"callback_url\":\"{_options.Square.CallbackUrl}/customer/callback\",\"client_id\":\"{_options.Square.AppId}\",\"notes\":\"OrderID:{order.Uuid}\",\"options\":{{\"supported_tender_types\":[\"CREDIT_CARD\"]}}}}";
        return new CustomerSquareRetryResponse(1, $"square-commerce-v1://payment/create?data={Uri.EscapeDataString(data)}", CustomerCheckoutSupport.ResolveHomepageLink(order.TourTimeSlot!.Tour!, _options));
    }

