[HttpGet("{orderId}/retrySquareTransaction")]
    public Task<CustomerSquareRetryResponse> RetrySquareTransaction(string orderId, CancellationToken cancellationToken)
    {
        return retryCustomerSquareTransactionQueryHandler.Handle(new RetryCustomerSquareTransactionQuery(orderId), cancellationToken);
    }

